INSERT INTO "audit_logs" ("id", "actor_id", "actor_email", "action", "entity_type", "entity_id", "old_values", "new_values", "metadata", "created_at", "merchant_id") VALUES ('d6d441eb-c6d7-49cc-b664-8dea1497cdf8', NULL, 'system', 'notifications.update', 'notifications', 'ba8854d0-4bc9-4047-bbe7-bf4751f21104', '{"subject":"We received your order {{order_number}}","template":"Hi {{customer_name}}, thanks for your order {{order_number}} ({{total}}). We will confirm it shortly. - {{store_name}}"}', '{"subject":"Order {{ order.name }} received","template":"{% assign accent = shop.accent_color | default: \"#111827\" %}<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Thank you for your order!</title>\n</head>\n<body style=\"margin:0;padding:0;background:#f4f5f7;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"background:#f4f5f7;\">\n<tr><td align=\"center\" style=\"padding:32px 12px;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"max-width:560px;background:#ffffff;border-radius:12px;font-family:-apple-system,BlinkMacSystemFont,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;color:#111827;\">\n<tr><td style=\"padding:28px 32px 0;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\"><tr>\n<td>{% if shop.logo_url %}<img src=\"{{ shop.logo_url }}\" alt=\"{{ shop.name }}\" height=\"36\" style=\"display:block;height:36px;max-width:180px;border:0;\">{% else %}<span style=\"font-size:20px;font-weight:700;color:#111827;\">{{ shop.name }}</span>{% endif %}</td>\n<td align=\"right\" style=\"font-size:13px;color:#6b7280;\">Order {{ order.name }}</td>\n</tr></table>\n</td></tr>\n<tr><td style=\"padding:24px 32px 4px;\">\n<h1 style=\"margin:0 0 12px;font-size:22px;line-height:1.3;color:#111827;\">Thank you for your order!</h1>\n<p style=\"margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;\">Hi {{ customer.first_name | default: \"there\" }}, we have received your order {{ order.name }}. We will call you shortly to confirm it before it ships.</p>\n</td></tr>\n{% if order.status_url %}<tr><td style=\"padding:12px 32px 4px;\">\n<a href=\"{{ order.status_url }}\" style=\"display:inline-block;background:{{ accent }};color:#ffffff;text-decoration:none;font-size:15px;font-weight:600;padding:12px 22px;border-radius:8px;\">View your order</a>\n</td></tr>{% endif %}\n<tr><td style=\"padding:8px 32px 0;\">\n<p style=\"margin:0 0 8px;font-size:13px;font-weight:600;text-transform:uppercase;letter-spacing:0.04em;color:#6b7280;\">Order summary</p>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-top:1px solid #e5e7eb;\">\n{% for item in order.line_items %}<tr>\n<td width=\"56\" style=\"padding:12px 12px 12px 0;border-bottom:1px solid #f3f4f6;vertical-align:top;\">{% if item.image_url %}<img src=\"{{ item.image_url }}\" alt=\"\" width=\"48\" height=\"48\" style=\"display:block;width:48px;height:48px;border-radius:8px;object-fit:cover;border:1px solid #e5e7eb;\">{% endif %}</td>\n<td style=\"padding:12px 0;border-bottom:1px solid #f3f4f6;font-size:14px;line-height:1.4;color:#111827;vertical-align:top;\">{{ item.title }}{% if item.variant_title %}<br><span style=\"color:#6b7280;font-size:13px;\">{{ item.variant_title }}</span>{% endif %}<br><span style=\"color:#6b7280;font-size:13px;\">Qty {{ item.quantity }}</span></td>\n<td align=\"right\" style=\"padding:12px 0;border-bottom:1px solid #f3f4f6;font-size:14px;color:#111827;vertical-align:top;white-space:nowrap;\">{{ item.line_price | money }}</td>\n</tr>{% endfor %}\n</table>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"margin-top:8px;\">\n<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Subtotal</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.subtotal_price | money }}</td></tr>\n{% if order.discount_price > 0 %}<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Discount</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">-{{ order.discount_price | money }}</td></tr>{% endif %}\n<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Delivery</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.delivery_price | money }}</td></tr>\n<tr><td style=\"padding:10px 0 6px;font-size:16px;font-weight:700;color:#111827;border-top:1px solid #e5e7eb;\">Total</td><td align=\"right\" style=\"padding:10px 0 6px;font-size:16px;font-weight:700;color:#111827;border-top:1px solid #e5e7eb;\">{{ order.total_price | money }}</td></tr>\n{% if order.paid_amount > 0 %}<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Paid</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.paid_amount | money }}</td></tr>{% endif %}\n{% if order.cod_amount > 0 %}<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\"><strong>To pay on delivery</strong></td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\"><strong>{{ order.cod_amount | money }}</strong></td></tr>{% endif %}\n</table>\n</td></tr>\n{% if order.shipping_address.address %}<tr><td style=\"padding:20px 32px 0;\">\n<p style=\"margin:0 0 6px;font-size:13px;font-weight:600;text-transform:uppercase;letter-spacing:0.04em;color:#6b7280;\">Delivery address</p>\n<p style=\"margin:0;font-size:14px;line-height:1.6;color:#374151;\">{{ order.shipping_address.name }}<br>{{ order.shipping_address.address }}{% if order.shipping_address.area %}, {{ order.shipping_address.area }}{% endif %}{% if order.shipping_address.district %}, {{ order.shipping_address.district }}{% endif %}<br>{{ order.shipping_address.phone }}</p>\n</td></tr>{% endif %}\n<tr><td style=\"padding:28px 32px 28px;\">\n<p style=\"margin:0;padding-top:20px;border-top:1px solid #e5e7eb;font-size:13px;line-height:1.6;color:#6b7280;\">{{ shop.name }}{% if shop.phone %} · {{ shop.phone }}{% endif %}{% if shop.email %} · {{ shop.email }}{% endif %}{% if shop.address %}<br>{{ shop.address }}{% endif %}</p>\n</td></tr>\n</table>\n</td></tr>\n</table>\n</body>\n</html>"}', '{}', '2026-10-24T23:22:45.532Z', '00000000-0000-4000-8000-000000000001');
INSERT INTO "audit_logs" ("id", "actor_id", "actor_email", "action", "entity_type", "entity_id", "old_values", "new_values", "metadata", "created_at", "merchant_id") VALUES ('e9bb2a10-76ac-49ed-a24f-c42c625ec3f9', NULL, 'system', 'notifications.update', 'notifications', 'bc778338-d499-4d44-aa2a-6ac3f8475261', '{"subject":"Order {{order_number}} confirmed","template":"Your order {{order_number}} is confirmed and being prepared. Total due on delivery: {{cod_amount}}. - {{store_name}}"}', '{"subject":"Order {{ order.name }} confirmed","template":"{% assign accent = shop.accent_color | default: \"#111827\" %}<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Your order is confirmed</title>\n</head>\n<body style=\"margin:0;padding:0;background:#f4f5f7;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"background:#f4f5f7;\">\n<tr><td align=\"center\" style=\"padding:32px 12px;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"max-width:560px;background:#ffffff;border-radius:12px;font-family:-apple-system,BlinkMacSystemFont,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;color:#111827;\">\n<tr><td style=\"padding:28px 32px 0;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\"><tr>\n<td>{% if shop.logo_url %}<img src=\"{{ shop.logo_url }}\" alt=\"{{ shop.name }}\" height=\"36\" style=\"display:block;height:36px;max-width:180px;border:0;\">{% else %}<span style=\"font-size:20px;font-weight:700;color:#111827;\">{{ shop.name }}</span>{% endif %}</td>\n<td align=\"right\" style=\"font-size:13px;color:#6b7280;\">Order {{ order.name }}</td>\n</tr></table>\n</td></tr>\n<tr><td style=\"padding:24px 32px 4px;\">\n<h1 style=\"margin:0 0 12px;font-size:22px;line-height:1.3;color:#111827;\">Your order is confirmed</h1>\n<p style=\"margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;\">Hi {{ customer.first_name | default: \"there\" }}, your order {{ order.name }} is confirmed and we are getting it ready.</p>\n{% if order.cod_amount > 0 %}<p style=\"margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;\">Please keep <strong>{{ order.cod_amount | money }}</strong> ready to pay on delivery.</p>{% endif %}\n</td></tr>\n{% if order.status_url %}<tr><td style=\"padding:12px 32px 4px;\">\n<a href=\"{{ order.status_url }}\" style=\"display:inline-block;background:{{ accent }};color:#ffffff;text-decoration:none;font-size:15px;font-weight:600;padding:12px 22px;border-radius:8px;\">View your order</a>\n</td></tr>{% endif %}\n<tr><td style=\"padding:8px 32px 0;\">\n<p style=\"margin:0 0 8px;font-size:13px;font-weight:600;text-transform:uppercase;letter-spacing:0.04em;color:#6b7280;\">Order summary</p>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-top:1px solid #e5e7eb;\">\n{% for item in order.line_items %}<tr>\n<td width=\"56\" style=\"padding:12px 12px 12px 0;border-bottom:1px solid #f3f4f6;vertical-align:top;\">{% if item.image_url %}<img src=\"{{ item.image_url }}\" alt=\"\" width=\"48\" height=\"48\" style=\"display:block;width:48px;height:48px;border-radius:8px;object-fit:cover;border:1px solid #e5e7eb;\">{% endif %}</td>\n<td style=\"padding:12px 0;border-bottom:1px solid #f3f4f6;font-size:14px;line-height:1.4;color:#111827;vertical-align:top;\">{{ item.title }}{% if item.variant_title %}<br><span style=\"color:#6b7280;font-size:13px;\">{{ item.variant_title }}</span>{% endif %}<br><span style=\"color:#6b7280;font-size:13px;\">Qty {{ item.quantity }}</span></td>\n<td align=\"right\" style=\"padding:12px 0;border-bottom:1px solid #f3f4f6;font-size:14px;color:#111827;vertical-align:top;white-space:nowrap;\">{{ item.line_price | money }}</td>\n</tr>{% endfor %}\n</table>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"margin-top:8px;\">\n<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Subtotal</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.subtotal_price | money }}</td></tr>\n{% if order.discount_price > 0 %}<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Discount</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">-{{ order.discount_price | money }}</td></tr>{% endif %}\n<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Delivery</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.delivery_price | money }}</td></tr>\n<tr><td style=\"padding:10px 0 6px;font-size:16px;font-weight:700;color:#111827;border-top:1px solid #e5e7eb;\">Total</td><td align=\"right\" style=\"padding:10px 0 6px;font-size:16px;font-weight:700;color:#111827;border-top:1px solid #e5e7eb;\">{{ order.total_price | money }}</td></tr>\n{% if order.paid_amount > 0 %}<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Paid</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.paid_amount | money }}</td></tr>{% endif %}\n{% if order.cod_amount > 0 %}<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\"><strong>To pay on delivery</strong></td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\"><strong>{{ order.cod_amount | money }}</strong></td></tr>{% endif %}\n</table>\n</td></tr>\n{% if order.shipping_address.address %}<tr><td style=\"padding:20px 32px 0;\">\n<p style=\"margin:0 0 6px;font-size:13px;font-weight:600;text-transform:uppercase;letter-spacing:0.04em;color:#6b7280;\">Delivery address</p>\n<p style=\"margin:0;font-size:14px;line-height:1.6;color:#374151;\">{{ order.shipping_address.name }}<br>{{ order.shipping_address.address }}{% if order.shipping_address.area %}, {{ order.shipping_address.area }}{% endif %}{% if order.shipping_address.district %}, {{ order.shipping_address.district }}{% endif %}<br>{{ order.shipping_address.phone }}</p>\n</td></tr>{% endif %}\n<tr><td style=\"padding:28px 32px 28px;\">\n<p style=\"margin:0;padding-top:20px;border-top:1px solid #e5e7eb;font-size:13px;line-height:1.6;color:#6b7280;\">{{ shop.name }}{% if shop.phone %} · {{ shop.phone }}{% endif %}{% if shop.email %} · {{ shop.email }}{% endif %}{% if shop.address %}<br>{{ shop.address }}{% endif %}</p>\n</td></tr>\n</table>\n</td></tr>\n</table>\n</body>\n</html>"}', '{}', '2026-10-24T23:22:45.532Z', '00000000-0000-4000-8000-000000000001');
INSERT INTO "audit_logs" ("id", "actor_id", "actor_email", "action", "entity_type", "entity_id", "old_values", "new_values", "metadata", "created_at", "merchant_id") VALUES ('dda19b10-2c37-409d-ae3d-d3b0ce25f769', NULL, 'system', 'notifications.update', 'notifications', 'e40ae5c0-6ce6-44ed-a190-3d5e8d676cc9', '{"subject":"Advance payment needed for {{order_number}}","template":"To confirm order {{order_number}}, please pay an advance of {{advance_amount}}. Pay here: {{track_order_url}} - {{store_name}}"}', '{"subject":"Advance payment needed for order {{ order.name }}","template":"{% assign accent = shop.accent_color | default: \"#111827\" %}<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>One more step to confirm your order</title>\n</head>\n<body style=\"margin:0;padding:0;background:#f4f5f7;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"background:#f4f5f7;\">\n<tr><td align=\"center\" style=\"padding:32px 12px;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"max-width:560px;background:#ffffff;border-radius:12px;font-family:-apple-system,BlinkMacSystemFont,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;color:#111827;\">\n<tr><td style=\"padding:28px 32px 0;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\"><tr>\n<td>{% if shop.logo_url %}<img src=\"{{ shop.logo_url }}\" alt=\"{{ shop.name }}\" height=\"36\" style=\"display:block;height:36px;max-width:180px;border:0;\">{% else %}<span style=\"font-size:20px;font-weight:700;color:#111827;\">{{ shop.name }}</span>{% endif %}</td>\n<td align=\"right\" style=\"font-size:13px;color:#6b7280;\">Order {{ order.name }}</td>\n</tr></table>\n</td></tr>\n<tr><td style=\"padding:24px 32px 4px;\">\n<h1 style=\"margin:0 0 12px;font-size:22px;line-height:1.3;color:#111827;\">One more step to confirm your order</h1>\n<p style=\"margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;\">Hi {{ customer.first_name | default: \"there\" }}, to confirm order {{ order.name }} please pay an advance of <strong>{{ order.advance_amount | money }}</strong>. The rest is paid on delivery.</p>\n</td></tr>\n{% if order.status_url %}<tr><td style=\"padding:12px 32px 4px;\">\n<a href=\"{{ order.status_url }}\" style=\"display:inline-block;background:{{ accent }};color:#ffffff;text-decoration:none;font-size:15px;font-weight:600;padding:12px 22px;border-radius:8px;\">Pay the advance</a>\n</td></tr>{% endif %}\n<tr><td style=\"padding:8px 32px 0;\">\n<p style=\"margin:0 0 8px;font-size:13px;font-weight:600;text-transform:uppercase;letter-spacing:0.04em;color:#6b7280;\">Order summary</p>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-top:1px solid #e5e7eb;\">\n{% for item in order.line_items %}<tr>\n<td width=\"56\" style=\"padding:12px 12px 12px 0;border-bottom:1px solid #f3f4f6;vertical-align:top;\">{% if item.image_url %}<img src=\"{{ item.image_url }}\" alt=\"\" width=\"48\" height=\"48\" style=\"display:block;width:48px;height:48px;border-radius:8px;object-fit:cover;border:1px solid #e5e7eb;\">{% endif %}</td>\n<td style=\"padding:12px 0;border-bottom:1px solid #f3f4f6;font-size:14px;line-height:1.4;color:#111827;vertical-align:top;\">{{ item.title }}{% if item.variant_title %}<br><span style=\"color:#6b7280;font-size:13px;\">{{ item.variant_title }}</span>{% endif %}<br><span style=\"color:#6b7280;font-size:13px;\">Qty {{ item.quantity }}</span></td>\n<td align=\"right\" style=\"padding:12px 0;border-bottom:1px solid #f3f4f6;font-size:14px;color:#111827;vertical-align:top;white-space:nowrap;\">{{ item.line_price | money }}</td>\n</tr>{% endfor %}\n</table>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"margin-top:8px;\">\n<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Subtotal</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.subtotal_price | money }}</td></tr>\n{% if order.discount_price > 0 %}<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Discount</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">-{{ order.discount_price | money }}</td></tr>{% endif %}\n<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Delivery</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.delivery_price | money }}</td></tr>\n<tr><td style=\"padding:10px 0 6px;font-size:16px;font-weight:700;color:#111827;border-top:1px solid #e5e7eb;\">Total</td><td align=\"right\" style=\"padding:10px 0 6px;font-size:16px;font-weight:700;color:#111827;border-top:1px solid #e5e7eb;\">{{ order.total_price | money }}</td></tr>\n{% if order.paid_amount > 0 %}<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Paid</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.paid_amount | money }}</td></tr>{% endif %}\n{% if order.cod_amount > 0 %}<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\"><strong>To pay on delivery</strong></td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\"><strong>{{ order.cod_amount | money }}</strong></td></tr>{% endif %}\n</table>\n</td></tr>\n{% if order.shipping_address.address %}<tr><td style=\"padding:20px 32px 0;\">\n<p style=\"margin:0 0 6px;font-size:13px;font-weight:600;text-transform:uppercase;letter-spacing:0.04em;color:#6b7280;\">Delivery address</p>\n<p style=\"margin:0;font-size:14px;line-height:1.6;color:#374151;\">{{ order.shipping_address.name }}<br>{{ order.shipping_address.address }}{% if order.shipping_address.area %}, {{ order.shipping_address.area }}{% endif %}{% if order.shipping_address.district %}, {{ order.shipping_address.district }}{% endif %}<br>{{ order.shipping_address.phone }}</p>\n</td></tr>{% endif %}\n<tr><td style=\"padding:28px 32px 28px;\">\n<p style=\"margin:0;padding-top:20px;border-top:1px solid #e5e7eb;font-size:13px;line-height:1.6;color:#6b7280;\">{{ shop.name }}{% if shop.phone %} · {{ shop.phone }}{% endif %}{% if shop.email %} · {{ shop.email }}{% endif %}{% if shop.address %}<br>{{ shop.address }}{% endif %}</p>\n</td></tr>\n</table>\n</td></tr>\n</table>\n</body>\n</html>"}', '{}', '2026-10-24T23:22:45.532Z', '00000000-0000-4000-8000-000000000001');
INSERT INTO "audit_logs" ("id", "actor_id", "actor_email", "action", "entity_type", "entity_id", "old_values", "new_values", "metadata", "created_at", "merchant_id") VALUES ('363c5106-fbc7-4cd5-a06d-3983630556b4', NULL, 'system', 'notifications.update', 'notifications', '5d290079-29da-4c83-b6a1-989630b3f9e1', '{"template":"Your order {{order_number}} has been handed to {{courier_name}}. Tracking: {{tracking_number}} {{tracking_url}} - {{store_name}}"}', '{"template":"Hi {{customer_first_name}}, your order {{order_number}} has been handed to {{courier_name}}. Tracking number: {{tracking_number}}. Track it here: {{tracking_url}} anytime.\n\nThe {{store_name}} team"}', '{}', '2026-10-24T23:22:45.532Z', '00000000-0000-4000-8000-000000000001');
INSERT INTO "audit_logs" ("id", "actor_id", "actor_email", "action", "entity_type", "entity_id", "old_values", "new_values", "metadata", "created_at", "merchant_id") VALUES ('79537ca1-e2d6-40f7-8f0a-dc6589147e5a', NULL, 'system', 'notifications.update', 'notifications', '306a26a2-332f-46c0-a692-7212971ed5d4', '{"template":"Your order {{order_number}} was delivered. We hope you love it! - {{store_name}}"}', '{"template":"Hi {{customer_first_name}}, your order {{order_number}} was delivered. We hope you love it! Reply here if anything is not right.\n\nThe {{store_name}} team"}', '{}', '2026-10-24T23:22:45.532Z', '00000000-0000-4000-8000-000000000001');
INSERT INTO "audit_logs" ("id", "actor_id", "actor_email", "action", "entity_type", "entity_id", "old_values", "new_values", "metadata", "created_at", "merchant_id") VALUES ('3e662cfc-c2ac-407c-8151-e4aec8011798', NULL, 'system', 'notifications.update', 'notifications', 'e435c412-66c9-47b5-b16f-52dd14660ccf', '{"subject":"Order {{order_number}} is on the way","template":"Your order {{order_number}} has been handed to {{courier_name}}. Tracking: {{tracking_number}} {{tracking_url}} - {{store_name}}"}', '{"subject":"Order {{ order.name }} is on the way","template":"{% assign accent = shop.accent_color | default: \"#111827\" %}<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Your order is on the way</title>\n</head>\n<body style=\"margin:0;padding:0;background:#f4f5f7;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"background:#f4f5f7;\">\n<tr><td align=\"center\" style=\"padding:32px 12px;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"max-width:560px;background:#ffffff;border-radius:12px;font-family:-apple-system,BlinkMacSystemFont,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;color:#111827;\">\n<tr><td style=\"padding:28px 32px 0;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\"><tr>\n<td>{% if shop.logo_url %}<img src=\"{{ shop.logo_url }}\" alt=\"{{ shop.name }}\" height=\"36\" style=\"display:block;height:36px;max-width:180px;border:0;\">{% else %}<span style=\"font-size:20px;font-weight:700;color:#111827;\">{{ shop.name }}</span>{% endif %}</td>\n<td align=\"right\" style=\"font-size:13px;color:#6b7280;\">Order {{ order.name }}</td>\n</tr></table>\n</td></tr>\n<tr><td style=\"padding:24px 32px 4px;\">\n<h1 style=\"margin:0 0 12px;font-size:22px;line-height:1.3;color:#111827;\">Your order is on the way</h1>\n<p style=\"margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;\">Hi {{ customer.first_name | default: \"there\" }}, your order {{ order.name }} has been handed to {{ shipment.courier | default: \"the courier\" }}.</p>\n{% if shipment.tracking_number %}<p style=\"margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;\">Tracking number: <strong>{{ shipment.tracking_number }}</strong></p>{% endif %}\n{% if order.cod_amount > 0 %}<p style=\"margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;\">Please keep <strong>{{ order.cod_amount | money }}</strong> ready to pay on delivery.</p>{% endif %}\n</td></tr>\n{% if shipment.tracking_url or order.status_url %}<tr><td style=\"padding:12px 32px 4px;\">\n<a href=\"{{ shipment.tracking_url | default: order.status_url }}\" style=\"display:inline-block;background:{{ accent }};color:#ffffff;text-decoration:none;font-size:15px;font-weight:600;padding:12px 22px;border-radius:8px;\">Track your parcel</a>\n</td></tr>{% endif %}\n<tr><td style=\"padding:8px 32px 0;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-top:1px solid #e5e7eb;\">\n<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Order</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.name }}</td></tr>\n<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Items</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.item_count }}</td></tr>\n<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Total</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.total_price | money }}</td></tr>\n{% if order.cod_amount > 0 %}<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">To pay on delivery</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.cod_amount | money }}</td></tr>{% endif %}\n</table>\n</td></tr>\n<tr><td style=\"padding:28px 32px 28px;\">\n<p style=\"margin:0;padding-top:20px;border-top:1px solid #e5e7eb;font-size:13px;line-height:1.6;color:#6b7280;\">{{ shop.name }}{% if shop.phone %} · {{ shop.phone }}{% endif %}{% if shop.email %} · {{ shop.email }}{% endif %}{% if shop.address %}<br>{{ shop.address }}{% endif %}</p>\n</td></tr>\n</table>\n</td></tr>\n</table>\n</body>\n</html>"}', '{}', '2026-10-24T23:22:45.532Z', '00000000-0000-4000-8000-000000000001');
INSERT INTO "audit_logs" ("id", "actor_id", "actor_email", "action", "entity_type", "entity_id", "old_values", "new_values", "metadata", "created_at", "merchant_id") VALUES ('ad0de531-c571-4a72-8bf5-f4d785e06d65', NULL, 'system', 'notifications.update', 'notifications', '2960ad11-7807-4c0b-ae74-79fa88b2fd62', '{"subject":"Order {{order_number}} delivered","template":"Your order {{order_number}} was delivered. We hope you love it! - {{store_name}}"}', '{"subject":"Order {{ order.name }} delivered","template":"{% assign accent = shop.accent_color | default: \"#111827\" %}<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Your order was delivered</title>\n</head>\n<body style=\"margin:0;padding:0;background:#f4f5f7;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"background:#f4f5f7;\">\n<tr><td align=\"center\" style=\"padding:32px 12px;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"max-width:560px;background:#ffffff;border-radius:12px;font-family:-apple-system,BlinkMacSystemFont,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;color:#111827;\">\n<tr><td style=\"padding:28px 32px 0;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\"><tr>\n<td>{% if shop.logo_url %}<img src=\"{{ shop.logo_url }}\" alt=\"{{ shop.name }}\" height=\"36\" style=\"display:block;height:36px;max-width:180px;border:0;\">{% else %}<span style=\"font-size:20px;font-weight:700;color:#111827;\">{{ shop.name }}</span>{% endif %}</td>\n<td align=\"right\" style=\"font-size:13px;color:#6b7280;\">Order {{ order.name }}</td>\n</tr></table>\n</td></tr>\n<tr><td style=\"padding:24px 32px 4px;\">\n<h1 style=\"margin:0 0 12px;font-size:22px;line-height:1.3;color:#111827;\">Your order was delivered</h1>\n<p style=\"margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;\">Hi {{ customer.first_name | default: \"there\" }}, your order {{ order.name }} was delivered. We hope you love it!</p>\n<p style=\"margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;\">If anything is not right, just reply to this email{% if shop.phone %} or call us at {{ shop.phone }}{% endif %}.</p>\n</td></tr>\n\n<tr><td style=\"padding:8px 32px 0;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-top:1px solid #e5e7eb;\">\n<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Order</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.name }}</td></tr>\n<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Items</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.item_count }}</td></tr>\n<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Total</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.total_price | money }}</td></tr>\n{% if order.cod_amount > 0 %}<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">To pay on delivery</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.cod_amount | money }}</td></tr>{% endif %}\n</table>\n</td></tr>\n<tr><td style=\"padding:28px 32px 28px;\">\n<p style=\"margin:0;padding-top:20px;border-top:1px solid #e5e7eb;font-size:13px;line-height:1.6;color:#6b7280;\">{{ shop.name }}{% if shop.phone %} · {{ shop.phone }}{% endif %}{% if shop.email %} · {{ shop.email }}{% endif %}{% if shop.address %}<br>{{ shop.address }}{% endif %}</p>\n</td></tr>\n</table>\n</td></tr>\n</table>\n</body>\n</html>"}', '{}', '2026-10-24T23:22:45.532Z', '00000000-0000-4000-8000-000000000001');
INSERT INTO "audit_logs" ("id", "actor_id", "actor_email", "action", "entity_type", "entity_id", "old_values", "new_values", "metadata", "created_at", "merchant_id") VALUES ('09062677-1431-4ec2-a398-348183d0de6b', NULL, 'system', 'notifications.update', 'notifications', '67ee39b2-9518-47ae-92c8-327412260fb1', '{"subject":"Order {{order_number}} cancelled","template":"Your order {{order_number}} has been cancelled. Questions? Call {{store_phone}}. - {{store_name}}"}', '{"subject":"Order {{ order.name }} cancelled","template":"{% assign accent = shop.accent_color | default: \"#111827\" %}<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Your order was cancelled</title>\n</head>\n<body style=\"margin:0;padding:0;background:#f4f5f7;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"background:#f4f5f7;\">\n<tr><td align=\"center\" style=\"padding:32px 12px;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"max-width:560px;background:#ffffff;border-radius:12px;font-family:-apple-system,BlinkMacSystemFont,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;color:#111827;\">\n<tr><td style=\"padding:28px 32px 0;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\"><tr>\n<td>{% if shop.logo_url %}<img src=\"{{ shop.logo_url }}\" alt=\"{{ shop.name }}\" height=\"36\" style=\"display:block;height:36px;max-width:180px;border:0;\">{% else %}<span style=\"font-size:20px;font-weight:700;color:#111827;\">{{ shop.name }}</span>{% endif %}</td>\n<td align=\"right\" style=\"font-size:13px;color:#6b7280;\">Order {{ order.name }}</td>\n</tr></table>\n</td></tr>\n<tr><td style=\"padding:24px 32px 4px;\">\n<h1 style=\"margin:0 0 12px;font-size:22px;line-height:1.3;color:#111827;\">Your order was cancelled</h1>\n<p style=\"margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;\">Hi {{ customer.first_name | default: \"there\" }}, your order {{ order.name }} has been cancelled.</p>\n{% if order.paid_amount > 0 %}<p style=\"margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;\">You paid {{ order.paid_amount | money }} for this order. We will contact you about the refund.</p>{% endif %}\n<p style=\"margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;\">Questions? Reply to this email{% if shop.phone %} or call us at {{ shop.phone }}{% endif %}.</p>\n</td></tr>\n\n<tr><td style=\"padding:8px 32px 0;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-top:1px solid #e5e7eb;\">\n<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Order</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.name }}</td></tr>\n<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Items</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.item_count }}</td></tr>\n<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Total</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.total_price | money }}</td></tr>\n{% if order.cod_amount > 0 %}<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">To pay on delivery</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.cod_amount | money }}</td></tr>{% endif %}\n</table>\n</td></tr>\n<tr><td style=\"padding:28px 32px 28px;\">\n<p style=\"margin:0;padding-top:20px;border-top:1px solid #e5e7eb;font-size:13px;line-height:1.6;color:#6b7280;\">{{ shop.name }}{% if shop.phone %} · {{ shop.phone }}{% endif %}{% if shop.email %} · {{ shop.email }}{% endif %}{% if shop.address %}<br>{{ shop.address }}{% endif %}</p>\n</td></tr>\n</table>\n</td></tr>\n</table>\n</body>\n</html>"}', '{}', '2026-10-24T23:22:45.532Z', '00000000-0000-4000-8000-000000000001');
INSERT INTO "audit_logs" ("id", "actor_id", "actor_email", "action", "entity_type", "entity_id", "old_values", "new_values", "metadata", "created_at", "merchant_id") VALUES ('da11f9f4-958f-4d01-8240-e5ff47046052', NULL, 'system', 'notifications.update', 'notifications', '80c5b3b3-569d-4196-b885-88fc8af0fde0', '{"subject":"Return received for {{order_number}}","template":"We have received the return for order {{order_number}}. - {{store_name}}"}', '{"subject":"Return received for order {{ order.name }}","template":"{% assign accent = shop.accent_color | default: \"#111827\" %}<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>We received your return</title>\n</head>\n<body style=\"margin:0;padding:0;background:#f4f5f7;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"background:#f4f5f7;\">\n<tr><td align=\"center\" style=\"padding:32px 12px;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"max-width:560px;background:#ffffff;border-radius:12px;font-family:-apple-system,BlinkMacSystemFont,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;color:#111827;\">\n<tr><td style=\"padding:28px 32px 0;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\"><tr>\n<td>{% if shop.logo_url %}<img src=\"{{ shop.logo_url }}\" alt=\"{{ shop.name }}\" height=\"36\" style=\"display:block;height:36px;max-width:180px;border:0;\">{% else %}<span style=\"font-size:20px;font-weight:700;color:#111827;\">{{ shop.name }}</span>{% endif %}</td>\n<td align=\"right\" style=\"font-size:13px;color:#6b7280;\">Order {{ order.name }}</td>\n</tr></table>\n</td></tr>\n<tr><td style=\"padding:24px 32px 4px;\">\n<h1 style=\"margin:0 0 12px;font-size:22px;line-height:1.3;color:#111827;\">We received your return</h1>\n<p style=\"margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;\">Hi {{ customer.first_name | default: \"there\" }}, the returned parcel for order {{ order.name }} has reached us.</p>\n{% if order.paid_amount > 0 %}<p style=\"margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;\">We will contact you about your payment of {{ order.paid_amount | money }}.</p>{% endif %}\n</td></tr>\n\n\n<tr><td style=\"padding:28px 32px 28px;\">\n<p style=\"margin:0;padding-top:20px;border-top:1px solid #e5e7eb;font-size:13px;line-height:1.6;color:#6b7280;\">{{ shop.name }}{% if shop.phone %} · {{ shop.phone }}{% endif %}{% if shop.email %} · {{ shop.email }}{% endif %}{% if shop.address %}<br>{{ shop.address }}{% endif %}</p>\n</td></tr>\n</table>\n</td></tr>\n</table>\n</body>\n</html>"}', '{}', '2026-10-24T23:22:45.532Z', '00000000-0000-4000-8000-000000000001');
INSERT INTO "audit_logs" ("id", "actor_id", "actor_email", "action", "entity_type", "entity_id", "old_values", "new_values", "metadata", "created_at", "merchant_id") VALUES ('e23937cd-cbde-4c6f-9d80-f663b8d97c6a', NULL, 'system', 'notifications.update', 'notifications', '1c273764-0dc7-4cc5-9358-d340bfec1b92', '{"subject":"Pre-order {{order_number}} confirmed","template":"Your pre-order {{order_number}} is confirmed. We will ship it as soon as it arrives in stock. - {{store_name}}"}', '{"subject":"Pre-order {{ order.name }} confirmed","template":"{% assign accent = shop.accent_color | default: \"#111827\" %}<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Your pre-order is confirmed</title>\n</head>\n<body style=\"margin:0;padding:0;background:#f4f5f7;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"background:#f4f5f7;\">\n<tr><td align=\"center\" style=\"padding:32px 12px;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"max-width:560px;background:#ffffff;border-radius:12px;font-family:-apple-system,BlinkMacSystemFont,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;color:#111827;\">\n<tr><td style=\"padding:28px 32px 0;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\"><tr>\n<td>{% if shop.logo_url %}<img src=\"{{ shop.logo_url }}\" alt=\"{{ shop.name }}\" height=\"36\" style=\"display:block;height:36px;max-width:180px;border:0;\">{% else %}<span style=\"font-size:20px;font-weight:700;color:#111827;\">{{ shop.name }}</span>{% endif %}</td>\n<td align=\"right\" style=\"font-size:13px;color:#6b7280;\">Order {{ order.name }}</td>\n</tr></table>\n</td></tr>\n<tr><td style=\"padding:24px 32px 4px;\">\n<h1 style=\"margin:0 0 12px;font-size:22px;line-height:1.3;color:#111827;\">Your pre-order is confirmed</h1>\n<p style=\"margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;\">Hi {{ customer.first_name | default: \"there\" }}, your pre-order {{ order.name }} is confirmed. We will ship it as soon as it arrives in stock.</p>\n</td></tr>\n{% if order.status_url %}<tr><td style=\"padding:12px 32px 4px;\">\n<a href=\"{{ order.status_url }}\" style=\"display:inline-block;background:{{ accent }};color:#ffffff;text-decoration:none;font-size:15px;font-weight:600;padding:12px 22px;border-radius:8px;\">View your order</a>\n</td></tr>{% endif %}\n<tr><td style=\"padding:8px 32px 0;\">\n<p style=\"margin:0 0 8px;font-size:13px;font-weight:600;text-transform:uppercase;letter-spacing:0.04em;color:#6b7280;\">Order summary</p>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-top:1px solid #e5e7eb;\">\n{% for item in order.line_items %}<tr>\n<td width=\"56\" style=\"padding:12px 12px 12px 0;border-bottom:1px solid #f3f4f6;vertical-align:top;\">{% if item.image_url %}<img src=\"{{ item.image_url }}\" alt=\"\" width=\"48\" height=\"48\" style=\"display:block;width:48px;height:48px;border-radius:8px;object-fit:cover;border:1px solid #e5e7eb;\">{% endif %}</td>\n<td style=\"padding:12px 0;border-bottom:1px solid #f3f4f6;font-size:14px;line-height:1.4;color:#111827;vertical-align:top;\">{{ item.title }}{% if item.variant_title %}<br><span style=\"color:#6b7280;font-size:13px;\">{{ item.variant_title }}</span>{% endif %}<br><span style=\"color:#6b7280;font-size:13px;\">Qty {{ item.quantity }}</span></td>\n<td align=\"right\" style=\"padding:12px 0;border-bottom:1px solid #f3f4f6;font-size:14px;color:#111827;vertical-align:top;white-space:nowrap;\">{{ item.line_price | money }}</td>\n</tr>{% endfor %}\n</table>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"margin-top:8px;\">\n<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Subtotal</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.subtotal_price | money }}</td></tr>\n{% if order.discount_price > 0 %}<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Discount</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">-{{ order.discount_price | money }}</td></tr>{% endif %}\n<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Delivery</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.delivery_price | money }}</td></tr>\n<tr><td style=\"padding:10px 0 6px;font-size:16px;font-weight:700;color:#111827;border-top:1px solid #e5e7eb;\">Total</td><td align=\"right\" style=\"padding:10px 0 6px;font-size:16px;font-weight:700;color:#111827;border-top:1px solid #e5e7eb;\">{{ order.total_price | money }}</td></tr>\n{% if order.paid_amount > 0 %}<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Paid</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.paid_amount | money }}</td></tr>{% endif %}\n{% if order.cod_amount > 0 %}<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\"><strong>To pay on delivery</strong></td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\"><strong>{{ order.cod_amount | money }}</strong></td></tr>{% endif %}\n</table>\n</td></tr>\n{% if order.shipping_address.address %}<tr><td style=\"padding:20px 32px 0;\">\n<p style=\"margin:0 0 6px;font-size:13px;font-weight:600;text-transform:uppercase;letter-spacing:0.04em;color:#6b7280;\">Delivery address</p>\n<p style=\"margin:0;font-size:14px;line-height:1.6;color:#374151;\">{{ order.shipping_address.name }}<br>{{ order.shipping_address.address }}{% if order.shipping_address.area %}, {{ order.shipping_address.area }}{% endif %}{% if order.shipping_address.district %}, {{ order.shipping_address.district }}{% endif %}<br>{{ order.shipping_address.phone }}</p>\n</td></tr>{% endif %}\n<tr><td style=\"padding:28px 32px 28px;\">\n<p style=\"margin:0;padding-top:20px;border-top:1px solid #e5e7eb;font-size:13px;line-height:1.6;color:#6b7280;\">{{ shop.name }}{% if shop.phone %} · {{ shop.phone }}{% endif %}{% if shop.email %} · {{ shop.email }}{% endif %}{% if shop.address %}<br>{{ shop.address }}{% endif %}</p>\n</td></tr>\n</table>\n</td></tr>\n</table>\n</body>\n</html>"}', '{}', '2026-10-24T23:22:45.532Z', '00000000-0000-4000-8000-000000000001');
INSERT INTO "audit_logs" ("id", "actor_id", "actor_email", "action", "entity_type", "entity_id", "old_values", "new_values", "metadata", "created_at", "merchant_id") VALUES ('774a4084-fd71-470b-8227-b6b7f5c1f2bd', NULL, 'system', 'notifications.update', 'notifications', '04b14beb-8554-413a-b575-6066fff58b53', '{"template":"Your order {{order_number}} has been cancelled. Questions? Call {{store_phone}}. - {{store_name}}"}', '{"template":"Hi {{customer_first_name}}, your order {{order_number}} has been cancelled. Questions? Call us at {{store_phone}} or reply here.\n\nThe {{store_name}} team"}', '{}', '2026-10-24T23:22:45.532Z', '00000000-0000-4000-8000-000000000001');
INSERT INTO "audit_logs" ("id", "actor_id", "actor_email", "action", "entity_type", "entity_id", "old_values", "new_values", "metadata", "created_at", "merchant_id") VALUES ('cc7f6a94-89d4-42b8-81d1-fee532b2918c', NULL, 'system', 'notifications.update', 'notifications', '6dceeb08-94d4-4c26-843a-57460389efc5', '{"template":"We have received the return for order {{order_number}}. - {{store_name}}"}', '{"template":"Hi {{customer_first_name}}, the returned parcel for order {{order_number}} has reached us. We will be in touch soon.\n\nThe {{store_name}} team"}', '{}', '2026-10-24T23:22:45.532Z', '00000000-0000-4000-8000-000000000001');
INSERT INTO "audit_logs" ("id", "actor_id", "actor_email", "action", "entity_type", "entity_id", "old_values", "new_values", "metadata", "created_at", "merchant_id") VALUES ('59b369b4-ca88-40a7-8eeb-e38fa778a2b3', NULL, 'system', 'notifications.update', 'notifications', '3b681cc9-d7f0-45dd-8909-16521ac778fa', '{"subject":"Order {{order_number}} is out for delivery","template":"Your order {{order_number}} is out for delivery today. Please keep {{cod_amount}} ready. - {{store_name}}"}', '{"subject":"Order {{ order.name }} is out for delivery","template":"{% assign accent = shop.accent_color | default: \"#111827\" %}<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Your order arrives today</title>\n</head>\n<body style=\"margin:0;padding:0;background:#f4f5f7;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"background:#f4f5f7;\">\n<tr><td align=\"center\" style=\"padding:32px 12px;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"max-width:560px;background:#ffffff;border-radius:12px;font-family:-apple-system,BlinkMacSystemFont,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;color:#111827;\">\n<tr><td style=\"padding:28px 32px 0;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\"><tr>\n<td>{% if shop.logo_url %}<img src=\"{{ shop.logo_url }}\" alt=\"{{ shop.name }}\" height=\"36\" style=\"display:block;height:36px;max-width:180px;border:0;\">{% else %}<span style=\"font-size:20px;font-weight:700;color:#111827;\">{{ shop.name }}</span>{% endif %}</td>\n<td align=\"right\" style=\"font-size:13px;color:#6b7280;\">Order {{ order.name }}</td>\n</tr></table>\n</td></tr>\n<tr><td style=\"padding:24px 32px 4px;\">\n<h1 style=\"margin:0 0 12px;font-size:22px;line-height:1.3;color:#111827;\">Your order arrives today</h1>\n<p style=\"margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;\">Hi {{ customer.first_name | default: \"there\" }}, your order {{ order.name }} is out for delivery today{% if shipment.courier %} with {{ shipment.courier }}{% endif %}.</p>\n{% if order.cod_amount > 0 %}<p style=\"margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;\">Please keep <strong>{{ order.cod_amount | money }}</strong> ready for the delivery person.</p>{% endif %}\n</td></tr>\n{% if shipment.tracking_url or order.status_url %}<tr><td style=\"padding:12px 32px 4px;\">\n<a href=\"{{ shipment.tracking_url | default: order.status_url }}\" style=\"display:inline-block;background:{{ accent }};color:#ffffff;text-decoration:none;font-size:15px;font-weight:600;padding:12px 22px;border-radius:8px;\">Track your parcel</a>\n</td></tr>{% endif %}\n\n<tr><td style=\"padding:28px 32px 28px;\">\n<p style=\"margin:0;padding-top:20px;border-top:1px solid #e5e7eb;font-size:13px;line-height:1.6;color:#6b7280;\">{{ shop.name }}{% if shop.phone %} · {{ shop.phone }}{% endif %}{% if shop.email %} · {{ shop.email }}{% endif %}{% if shop.address %}<br>{{ shop.address }}{% endif %}</p>\n</td></tr>\n</table>\n</td></tr>\n</table>\n</body>\n</html>"}', '{}', '2026-10-24T23:22:45.532Z', '00000000-0000-4000-8000-000000000001');
INSERT INTO "audit_logs" ("id", "actor_id", "actor_email", "action", "entity_type", "entity_id", "old_values", "new_values", "metadata", "created_at", "merchant_id") VALUES ('b8b23c2f-d312-4e1f-a09f-db6fba8155d8', NULL, 'system', 'notifications.update', 'notifications', '0745c088-aa60-4846-b4f3-2f922bcdda3e', '{"subject":"Order {{order_number}} is being returned","template":"Your order {{order_number}} is being returned to us. Questions? Call {{store_phone}}. - {{store_name}}"}', '{"subject":"Order {{ order.name }} is being returned","template":"{% assign accent = shop.accent_color | default: \"#111827\" %}<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Your order is being returned</title>\n</head>\n<body style=\"margin:0;padding:0;background:#f4f5f7;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"background:#f4f5f7;\">\n<tr><td align=\"center\" style=\"padding:32px 12px;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"max-width:560px;background:#ffffff;border-radius:12px;font-family:-apple-system,BlinkMacSystemFont,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;color:#111827;\">\n<tr><td style=\"padding:28px 32px 0;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\"><tr>\n<td>{% if shop.logo_url %}<img src=\"{{ shop.logo_url }}\" alt=\"{{ shop.name }}\" height=\"36\" style=\"display:block;height:36px;max-width:180px;border:0;\">{% else %}<span style=\"font-size:20px;font-weight:700;color:#111827;\">{{ shop.name }}</span>{% endif %}</td>\n<td align=\"right\" style=\"font-size:13px;color:#6b7280;\">Order {{ order.name }}</td>\n</tr></table>\n</td></tr>\n<tr><td style=\"padding:24px 32px 4px;\">\n<h1 style=\"margin:0 0 12px;font-size:22px;line-height:1.3;color:#111827;\">Your order is being returned</h1>\n<p style=\"margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;\">Hi {{ customer.first_name | default: \"there\" }}, the parcel for order {{ order.name }} is on its way back to us.</p>\n<p style=\"margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;\">Questions? Reply to this email{% if shop.phone %} or call us at {{ shop.phone }}{% endif %}.</p>\n</td></tr>\n\n\n<tr><td style=\"padding:28px 32px 28px;\">\n<p style=\"margin:0;padding-top:20px;border-top:1px solid #e5e7eb;font-size:13px;line-height:1.6;color:#6b7280;\">{{ shop.name }}{% if shop.phone %} · {{ shop.phone }}{% endif %}{% if shop.email %} · {{ shop.email }}{% endif %}{% if shop.address %}<br>{{ shop.address }}{% endif %}</p>\n</td></tr>\n</table>\n</td></tr>\n</table>\n</body>\n</html>"}', '{}', '2026-10-24T23:22:45.532Z', '00000000-0000-4000-8000-000000000001');
INSERT INTO "audit_logs" ("id", "actor_id", "actor_email", "action", "entity_type", "entity_id", "old_values", "new_values", "metadata", "created_at", "merchant_id") VALUES ('a8345768-60be-4575-ad71-70af13bf3570', NULL, 'system', 'notifications.update', 'notifications', '74658a64-0d63-4c3a-b488-8a6e4a9e6656', '{"subject":"Payment for {{order_number}} did not go through","template":"Your payment of {{payment_amount}} for order {{order_number}} did not go through. Try again: {{track_order_url}} - {{store_name}}"}', '{"subject":"Payment for order {{ order.name }} did not go through","template":"{% assign accent = shop.accent_color | default: \"#111827\" %}<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Your payment didn''t go through</title>\n</head>\n<body style=\"margin:0;padding:0;background:#f4f5f7;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"background:#f4f5f7;\">\n<tr><td align=\"center\" style=\"padding:32px 12px;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"max-width:560px;background:#ffffff;border-radius:12px;font-family:-apple-system,BlinkMacSystemFont,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;color:#111827;\">\n<tr><td style=\"padding:28px 32px 0;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\"><tr>\n<td>{% if shop.logo_url %}<img src=\"{{ shop.logo_url }}\" alt=\"{{ shop.name }}\" height=\"36\" style=\"display:block;height:36px;max-width:180px;border:0;\">{% else %}<span style=\"font-size:20px;font-weight:700;color:#111827;\">{{ shop.name }}</span>{% endif %}</td>\n<td align=\"right\" style=\"font-size:13px;color:#6b7280;\">Order {{ order.name }}</td>\n</tr></table>\n</td></tr>\n<tr><td style=\"padding:24px 32px 4px;\">\n<h1 style=\"margin:0 0 12px;font-size:22px;line-height:1.3;color:#111827;\">Your payment didn''t go through</h1>\n<p style=\"margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;\">Hi {{ customer.first_name | default: \"there\" }}, your payment of <strong>{{ payment.amount | money }}</strong> for order {{ order.name }} did not go through. No money was taken. You can try again below.</p>\n</td></tr>\n{% if order.status_url %}<tr><td style=\"padding:12px 32px 4px;\">\n<a href=\"{{ order.status_url }}\" style=\"display:inline-block;background:{{ accent }};color:#ffffff;text-decoration:none;font-size:15px;font-weight:600;padding:12px 22px;border-radius:8px;\">Try again</a>\n</td></tr>{% endif %}\n<tr><td style=\"padding:8px 32px 0;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-top:1px solid #e5e7eb;\">\n<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Order</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.name }}</td></tr>\n<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Items</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.item_count }}</td></tr>\n<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Total</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.total_price | money }}</td></tr>\n{% if order.cod_amount > 0 %}<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">To pay on delivery</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.cod_amount | money }}</td></tr>{% endif %}\n</table>\n</td></tr>\n<tr><td style=\"padding:28px 32px 28px;\">\n<p style=\"margin:0;padding-top:20px;border-top:1px solid #e5e7eb;font-size:13px;line-height:1.6;color:#6b7280;\">{{ shop.name }}{% if shop.phone %} · {{ shop.phone }}{% endif %}{% if shop.email %} · {{ shop.email }}{% endif %}{% if shop.address %}<br>{{ shop.address }}{% endif %}</p>\n</td></tr>\n</table>\n</td></tr>\n</table>\n</body>\n</html>"}', '{}', '2026-10-24T23:22:45.532Z', '00000000-0000-4000-8000-000000000001');
INSERT INTO "audit_logs" ("id", "actor_id", "actor_email", "action", "entity_type", "entity_id", "old_values", "new_values", "metadata", "created_at", "merchant_id") VALUES ('79c693eb-d399-4fff-a96e-8119ae37ff61', NULL, 'system', 'notifications.update', 'notifications', '4675e7cf-7cf6-4821-8f01-1bdf9dd589c9', '{"subject":"Payment received for {{order_number}}","template":"We received {{payment_amount}} for order {{order_number}}. Thank you! - {{store_name}}"}', '{"subject":"Payment received for order {{ order.name }}","template":"{% assign accent = shop.accent_color | default: \"#111827\" %}<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>We received your payment</title>\n</head>\n<body style=\"margin:0;padding:0;background:#f4f5f7;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"background:#f4f5f7;\">\n<tr><td align=\"center\" style=\"padding:32px 12px;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"max-width:560px;background:#ffffff;border-radius:12px;font-family:-apple-system,BlinkMacSystemFont,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;color:#111827;\">\n<tr><td style=\"padding:28px 32px 0;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\"><tr>\n<td>{% if shop.logo_url %}<img src=\"{{ shop.logo_url }}\" alt=\"{{ shop.name }}\" height=\"36\" style=\"display:block;height:36px;max-width:180px;border:0;\">{% else %}<span style=\"font-size:20px;font-weight:700;color:#111827;\">{{ shop.name }}</span>{% endif %}</td>\n<td align=\"right\" style=\"font-size:13px;color:#6b7280;\">Order {{ order.name }}</td>\n</tr></table>\n</td></tr>\n<tr><td style=\"padding:24px 32px 4px;\">\n<h1 style=\"margin:0 0 12px;font-size:22px;line-height:1.3;color:#111827;\">We received your payment</h1>\n<p style=\"margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;\">Hi {{ customer.first_name | default: \"there\" }}, we received <strong>{{ payment.amount | money }}</strong> for order {{ order.name }}. Thank you!</p>\n{% if order.due_amount > 0 %}<p style=\"margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;\">Still to pay on delivery: <strong>{{ order.due_amount | money }}</strong>.</p>{% endif %}\n</td></tr>\n\n<tr><td style=\"padding:8px 32px 0;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-top:1px solid #e5e7eb;\">\n<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Order</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.name }}</td></tr>\n<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Items</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.item_count }}</td></tr>\n<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Total</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.total_price | money }}</td></tr>\n{% if order.cod_amount > 0 %}<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">To pay on delivery</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.cod_amount | money }}</td></tr>{% endif %}\n</table>\n</td></tr>\n<tr><td style=\"padding:28px 32px 28px;\">\n<p style=\"margin:0;padding-top:20px;border-top:1px solid #e5e7eb;font-size:13px;line-height:1.6;color:#6b7280;\">{{ shop.name }}{% if shop.phone %} · {{ shop.phone }}{% endif %}{% if shop.email %} · {{ shop.email }}{% endif %}{% if shop.address %}<br>{{ shop.address }}{% endif %}</p>\n</td></tr>\n</table>\n</td></tr>\n</table>\n</body>\n</html>"}', '{}', '2026-10-24T23:22:45.532Z', '00000000-0000-4000-8000-000000000001');
INSERT INTO "audit_logs" ("id", "actor_id", "actor_email", "action", "entity_type", "entity_id", "old_values", "new_values", "metadata", "created_at", "merchant_id") VALUES ('82fc143a-b3a2-439e-a96a-6ae455a4c1ce', NULL, 'system', 'notifications.update', 'notifications', '06c29f05-6804-4934-9484-fab627c7096f', '{"template":"Hi {{customer_name}}, thanks for your order {{order_number}} ({{total}}). We will confirm it shortly. - {{store_name}}"}', '{"template":"Hi {{customer_first_name}}, thank you for your order {{order_number}} of {{total}}. We will call you shortly to confirm it.\n\nThank you for shopping with {{store_name}} today."}', '{}', '2026-10-24T23:22:45.532Z', '00000000-0000-4000-8000-000000000001');
INSERT INTO "audit_logs" ("id", "actor_id", "actor_email", "action", "entity_type", "entity_id", "old_values", "new_values", "metadata", "created_at", "merchant_id") VALUES ('9e673aef-4049-44bf-95ef-1b6937a94c90', NULL, 'system', 'notifications.update', 'notifications', 'fcce1bfb-15ee-40e3-a2b1-6955c593235c', '{"template":"Your order {{order_number}} is confirmed and being prepared. Total due on delivery: {{cod_amount}}. - {{store_name}}"}', '{"template":"Hi {{customer_first_name}}, your order {{order_number}} is confirmed and we are getting it ready. Amount to pay on delivery: {{cod_amount}}.\n\nThank you, the {{store_name}} team"}', '{}', '2026-10-24T23:22:45.532Z', '00000000-0000-4000-8000-000000000001');
INSERT INTO "audit_logs" ("id", "actor_id", "actor_email", "action", "entity_type", "entity_id", "old_values", "new_values", "metadata", "created_at", "merchant_id") VALUES ('5b0fecdb-de49-4bc0-82c5-ccdc1eff997a', NULL, 'system', 'notifications.update', 'notifications', '6a16d1e3-ce66-466e-aad1-942d2e1b5f10', '{"template":"To confirm order {{order_number}}, please pay an advance of {{advance_amount}}. Pay here: {{track_order_url}} - {{store_name}}"}', '{"template":"Hi {{customer_first_name}}, to confirm order {{order_number}} please pay an advance of {{advance_amount}} here: {{track_order_url}} and we will ship it right away.\n\nThank you, the {{store_name}} team"}', '{}', '2026-10-24T23:22:45.532Z', '00000000-0000-4000-8000-000000000001');
INSERT INTO "audit_logs" ("id", "actor_id", "actor_email", "action", "entity_type", "entity_id", "old_values", "new_values", "metadata", "created_at", "merchant_id") VALUES ('f69834b8-a4dc-4fff-8d81-aa45da7e0c6a', NULL, 'system', 'notifications.update', 'notifications', 'b98b4f9b-5219-46b7-8a0c-ebbbb5bc42f0', '{"template":"Your pre-order {{order_number}} is confirmed. We will ship it as soon as it arrives in stock. - {{store_name}}"}', '{"template":"Hi {{customer_first_name}}, your pre-order {{order_number}} is confirmed. We will ship it as soon as it arrives in stock.\n\nThank you, the {{store_name}} team"}', '{}', '2026-10-24T23:22:45.532Z', '00000000-0000-4000-8000-000000000001');
INSERT INTO "audit_logs" ("id", "actor_id", "actor_email", "action", "entity_type", "entity_id", "old_values", "new_values", "metadata", "created_at", "merchant_id") VALUES ('2c9af6e0-ad3a-48eb-8860-5b9cf9c3c962', NULL, 'system', 'notifications.update', 'notifications', 'c9a3e959-1db9-4a51-8a8b-d04fc855577f', '{"template":"Your order {{order_number}} is out for delivery today. Please keep {{cod_amount}} ready. - {{store_name}}"}', '{"template":"Hi {{customer_first_name}}, your order {{order_number}} is out for delivery today. Please keep {{cod_amount}} ready for the delivery person.\n\nThe {{store_name}} team"}', '{}', '2026-10-24T23:22:45.532Z', '00000000-0000-4000-8000-000000000001');
INSERT INTO "audit_logs" ("id", "actor_id", "actor_email", "action", "entity_type", "entity_id", "old_values", "new_values", "metadata", "created_at", "merchant_id") VALUES ('97618e06-52d1-4744-be4f-4403ada8b2b5', NULL, 'system', 'notifications.update', 'notifications', '5f07564c-08af-4644-a9af-0b9df1c1f7e7', '{"template":"Your order {{order_number}} is being returned to us. Questions? Call {{store_phone}}. - {{store_name}}"}', '{"template":"Hi {{customer_first_name}}, the parcel for order {{order_number}} is on its way back to us. Questions? Call us at {{store_phone}} or reply here.\n\nThe {{store_name}} team"}', '{}', '2026-10-24T23:22:45.532Z', '00000000-0000-4000-8000-000000000001');
INSERT INTO "audit_logs" ("id", "actor_id", "actor_email", "action", "entity_type", "entity_id", "old_values", "new_values", "metadata", "created_at", "merchant_id") VALUES ('cd1c7c91-3e60-465a-9146-51e2223813b4', NULL, 'system', 'notifications.update', 'notifications', '053bb3ec-09e3-4c0b-8869-176a73f1a7b3', '{"template":"Your payment of {{payment_amount}} for order {{order_number}} did not go through. Try again: {{track_order_url}} - {{store_name}}"}', '{"template":"Hi {{customer_first_name}}, your payment of {{payment_amount}} for order {{order_number}} did not go through. You can try again here: {{track_order_url}} at any time.\n\nThe {{store_name}} team"}', '{}', '2026-10-24T23:22:45.532Z', '00000000-0000-4000-8000-000000000001');
INSERT INTO "audit_logs" ("id", "actor_id", "actor_email", "action", "entity_type", "entity_id", "old_values", "new_values", "metadata", "created_at", "merchant_id") VALUES ('58699ff0-b069-468f-8f66-86be5ea4ddad', NULL, 'system', 'notifications.update', 'notifications', 'b9700eda-6751-40d6-bff0-957757b0696f', '{"template":"We received {{payment_amount}} for order {{order_number}}. Thank you! - {{store_name}}"}', '{"template":"Hi {{customer_first_name}}, we received your payment of {{payment_amount}} for order {{order_number}}. Thank you!\n\nThe {{store_name}} team"}', '{}', '2026-10-24T23:22:45.532Z', '00000000-0000-4000-8000-000000000001');
INSERT INTO "audit_logs" ("id", "actor_id", "actor_email", "action", "entity_type", "entity_id", "old_values", "new_values", "metadata", "created_at", "merchant_id") VALUES ('ac861122-0e23-4d53-a0cb-b1193da1afb8', NULL, 'system', 'notifications.update', 'notifications', 'ba8854d0-4bc9-4047-bbe7-bf4751f21104', '{"template":"{% assign accent = shop.accent_color | default: \"#111827\" %}<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Thank you for your order!</title>\n</head>\n<body style=\"margin:0;padding:0;background:#f4f5f7;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"background:#f4f5f7;\">\n<tr><td align=\"center\" style=\"padding:32px 12px;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"max-width:560px;background:#ffffff;border-radius:12px;font-family:-apple-system,BlinkMacSystemFont,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;color:#111827;\">\n<tr><td style=\"padding:28px 32px 0;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\"><tr>\n<td>{% if shop.logo_url %}<img src=\"{{ shop.logo_url }}\" alt=\"{{ shop.name }}\" height=\"36\" style=\"display:block;height:36px;max-width:180px;border:0;\">{% else %}<span style=\"font-size:20px;font-weight:700;color:#111827;\">{{ shop.name }}</span>{% endif %}</td>\n<td align=\"right\" style=\"font-size:13px;color:#6b7280;\">Order {{ order.name }}</td>\n</tr></table>\n</td></tr>\n<tr><td style=\"padding:24px 32px 4px;\">\n<h1 style=\"margin:0 0 12px;font-size:22px;line-height:1.3;color:#111827;\">Thank you for your order!</h1>\n<p style=\"margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;\">Hi {{ customer.first_name | default: \"there\" }}, we have received your order {{ order.name }}. We will call you shortly to confirm it before it ships.</p>\n</td></tr>\n{% if order.status_url %}<tr><td style=\"padding:12px 32px 4px;\">\n<a href=\"{{ order.status_url }}\" style=\"display:inline-block;background:{{ accent }};color:#ffffff;text-decoration:none;font-size:15px;font-weight:600;padding:12px 22px;border-radius:8px;\">View your order</a>\n</td></tr>{% endif %}\n<tr><td style=\"padding:8px 32px 0;\">\n<p style=\"margin:0 0 8px;font-size:13px;font-weight:600;text-transform:uppercase;letter-spacing:0.04em;color:#6b7280;\">Order summary</p>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-top:1px solid #e5e7eb;\">\n{% for item in order.line_items %}<tr>\n<td width=\"56\" style=\"padding:12px 12px 12px 0;border-bottom:1px solid #f3f4f6;vertical-align:top;\">{% if item.image_url %}<img src=\"{{ item.image_url }}\" alt=\"\" width=\"48\" height=\"48\" style=\"display:block;width:48px;height:48px;border-radius:8px;object-fit:cover;border:1px solid #e5e7eb;\">{% endif %}</td>\n<td style=\"padding:12px 0;border-bottom:1px solid #f3f4f6;font-size:14px;line-height:1.4;color:#111827;vertical-align:top;\">{{ item.title }}{% if item.variant_title %}<br><span style=\"color:#6b7280;font-size:13px;\">{{ item.variant_title }}</span>{% endif %}<br><span style=\"color:#6b7280;font-size:13px;\">Qty {{ item.quantity }}</span></td>\n<td align=\"right\" style=\"padding:12px 0;border-bottom:1px solid #f3f4f6;font-size:14px;color:#111827;vertical-align:top;white-space:nowrap;\">{{ item.line_price | money }}</td>\n</tr>{% endfor %}\n</table>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"margin-top:8px;\">\n<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Subtotal</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.subtotal_price | money }}</td></tr>\n{% if order.discount_price > 0 %}<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Discount</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">-{{ order.discount_price | money }}</td></tr>{% endif %}\n<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Delivery</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.delivery_price | money }}</td></tr>\n<tr><td style=\"padding:10px 0 6px;font-size:16px;font-weight:700;color:#111827;border-top:1px solid #e5e7eb;\">Total</td><td align=\"right\" style=\"padding:10px 0 6px;font-size:16px;font-weight:700;color:#111827;border-top:1px solid #e5e7eb;\">{{ order.total_price | money }}</td></tr>\n{% if order.paid_amount > 0 %}<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Paid</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.paid_amount | money }}</td></tr>{% endif %}\n{% if order.cod_amount > 0 %}<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\"><strong>To pay on delivery</strong></td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\"><strong>{{ order.cod_amount | money }}</strong></td></tr>{% endif %}\n</table>\n</td></tr>\n{% if order.shipping_address.address %}<tr><td style=\"padding:20px 32px 0;\">\n<p style=\"margin:0 0 6px;font-size:13px;font-weight:600;text-transform:uppercase;letter-spacing:0.04em;color:#6b7280;\">Delivery address</p>\n<p style=\"margin:0;font-size:14px;line-height:1.6;color:#374151;\">{{ order.shipping_address.name }}<br>{{ order.shipping_address.address }}{% if order.shipping_address.area %}, {{ order.shipping_address.area }}{% endif %}{% if order.shipping_address.district %}, {{ order.shipping_address.district }}{% endif %}<br>{{ order.shipping_address.phone }}</p>\n</td></tr>{% endif %}\n<tr><td style=\"padding:28px 32px 28px;\">\n<p style=\"margin:0;padding-top:20px;border-top:1px solid #e5e7eb;font-size:13px;line-height:1.6;color:#6b7280;\">{{ shop.name }}{% if shop.phone %} · {{ shop.phone }}{% endif %}{% if shop.email %} · {{ shop.email }}{% endif %}{% if shop.address %}<br>{{ shop.address }}{% endif %}</p>\n</td></tr>\n</table>\n</td></tr>\n</table>\n</body>\n</html>"}', '{"template":"{% assign accent = shop.accent_color | default: \"#111827\" %}<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Thank you for your order!</title>\n</head>\n<body style=\"margin:0;padding:0;background:#f4f5f7;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"background:#f4f5f7;\">\n<tr><td align=\"center\" style=\"padding:32px 12px;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"max-width:560px;background:#ffffff;border-radius:12px;font-family:-apple-system,BlinkMacSystemFont,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;color:#111827;\">\n<tr><td style=\"padding:28px 32px 0;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\"><tr>\n<td>{% if shop.logo_url %}<img src=\"{{ shop.logo_url }}\" alt=\"{{ shop.name }}\" height=\"36\" style=\"display:block;height:36px;max-width:180px;border:0;\">{% else %}<span style=\"font-size:20px;font-weight:700;color:#111827;\">{{ shop.name }}</span>{% endif %}</td>\n<td align=\"right\" style=\"font-size:13px;color:#6b7280;\">{% if order.name %}Order {{ order.name }}{% endif %}</td>\n</tr></table>\n</td></tr>\n<tr><td style=\"padding:24px 32px 4px;\">\n<h1 style=\"margin:0 0 12px;font-size:22px;line-height:1.3;color:#111827;\">Thank you for your order!</h1>\n<p style=\"margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;\">Hi {{ customer.first_name | default: \"there\" }}, we have received your order {{ order.name }}.{% if order.reply_url %} Please confirm it below so we can send it quickly.{% else %} We will call you shortly to confirm it before it ships.{% endif %}</p>\n</td></tr>\n{% if order.reply_url %}<tr><td style=\"padding:12px 32px 4px;\">\n<a href=\"{{ order.reply_url }}\" style=\"display:inline-block;background:{{ accent }};color:#ffffff;text-decoration:none;font-size:15px;font-weight:600;padding:12px 22px;border-radius:8px;\">Confirm your order</a>\n<p style=\"margin:12px 0 0;font-size:13px;line-height:1.6;color:#6b7280;\">Can''t take this order? <a href=\"{{ order.reply_url }}?action=cancel\" style=\"color:#6b7280;\">Cancel it here</a></p>\n</td></tr>{% else %}{% if order.status_url %}<tr><td style=\"padding:12px 32px 4px;\">\n<a href=\"{{ order.status_url }}\" style=\"display:inline-block;background:{{ accent }};color:#ffffff;text-decoration:none;font-size:15px;font-weight:600;padding:12px 22px;border-radius:8px;\">View your order</a>\n</td></tr>{% endif %}{% endif %}\n<tr><td style=\"padding:8px 32px 0;\">\n<p style=\"margin:0 0 8px;font-size:13px;font-weight:600;text-transform:uppercase;letter-spacing:0.04em;color:#6b7280;\">Order summary</p>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-top:1px solid #e5e7eb;\">\n{% for item in order.line_items %}<tr>\n<td width=\"56\" style=\"padding:12px 12px 12px 0;border-bottom:1px solid #f3f4f6;vertical-align:top;\">{% if item.image_url %}<img src=\"{{ item.image_url }}\" alt=\"\" width=\"48\" height=\"48\" style=\"display:block;width:48px;height:48px;border-radius:8px;object-fit:cover;border:1px solid #e5e7eb;\">{% endif %}</td>\n<td style=\"padding:12px 0;border-bottom:1px solid #f3f4f6;font-size:14px;line-height:1.4;color:#111827;vertical-align:top;\">{{ item.title }}{% if item.variant_title %}<br><span style=\"color:#6b7280;font-size:13px;\">{{ item.variant_title }}</span>{% endif %}<br><span style=\"color:#6b7280;font-size:13px;\">Qty {{ item.quantity }}</span></td>\n<td align=\"right\" style=\"padding:12px 0;border-bottom:1px solid #f3f4f6;font-size:14px;color:#111827;vertical-align:top;white-space:nowrap;\">{{ item.line_price | money }}</td>\n</tr>{% endfor %}\n</table>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"margin-top:8px;\">\n<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Subtotal</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.subtotal_price | money }}</td></tr>\n{% if order.discount_price > 0 %}<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Discount</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">-{{ order.discount_price | money }}</td></tr>{% endif %}\n<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Delivery</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.delivery_price | money }}</td></tr>\n<tr><td style=\"padding:10px 0 6px;font-size:16px;font-weight:700;color:#111827;border-top:1px solid #e5e7eb;\">Total</td><td align=\"right\" style=\"padding:10px 0 6px;font-size:16px;font-weight:700;color:#111827;border-top:1px solid #e5e7eb;\">{{ order.total_price | money }}</td></tr>\n{% if order.paid_amount > 0 %}<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Paid</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.paid_amount | money }}</td></tr>{% endif %}\n{% if order.cod_amount > 0 %}<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\"><strong>To pay on delivery</strong></td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\"><strong>{{ order.cod_amount | money }}</strong></td></tr>{% endif %}\n</table>\n</td></tr>\n{% if order.shipping_address.address %}<tr><td style=\"padding:20px 32px 0;\">\n<p style=\"margin:0 0 6px;font-size:13px;font-weight:600;text-transform:uppercase;letter-spacing:0.04em;color:#6b7280;\">Delivery address</p>\n<p style=\"margin:0;font-size:14px;line-height:1.6;color:#374151;\">{{ order.shipping_address.name }}<br>{{ order.shipping_address.address }}{% if order.shipping_address.area %}, {{ order.shipping_address.area }}{% endif %}{% if order.shipping_address.district %}, {{ order.shipping_address.district }}{% endif %}<br>{{ order.shipping_address.phone }}</p>\n</td></tr>{% endif %}\n<tr><td style=\"padding:28px 32px 28px;\">\n<p style=\"margin:0;padding-top:20px;border-top:1px solid #e5e7eb;font-size:13px;line-height:1.6;color:#6b7280;\">{{ shop.name }}{% if shop.phone %} · {{ shop.phone }}{% endif %}{% if shop.email %} · {{ shop.email }}{% endif %}{% if shop.address %}<br>{{ shop.address }}{% endif %}</p>\n</td></tr>\n</table>\n</td></tr>\n</table>\n</body>\n</html>"}', '{}', '2026-10-24T23:22:45.560Z', '00000000-0000-4000-8000-000000000001');
INSERT INTO "audit_logs" ("id", "actor_id", "actor_email", "action", "entity_type", "entity_id", "old_values", "new_values", "metadata", "created_at", "merchant_id") VALUES ('50747355-57e4-4a75-bb4c-ee6f1498dc95', NULL, 'system', 'notifications.update', 'notifications', 'bc778338-d499-4d44-aa2a-6ac3f8475261', '{"template":"{% assign accent = shop.accent_color | default: \"#111827\" %}<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Your order is confirmed</title>\n</head>\n<body style=\"margin:0;padding:0;background:#f4f5f7;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"background:#f4f5f7;\">\n<tr><td align=\"center\" style=\"padding:32px 12px;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"max-width:560px;background:#ffffff;border-radius:12px;font-family:-apple-system,BlinkMacSystemFont,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;color:#111827;\">\n<tr><td style=\"padding:28px 32px 0;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\"><tr>\n<td>{% if shop.logo_url %}<img src=\"{{ shop.logo_url }}\" alt=\"{{ shop.name }}\" height=\"36\" style=\"display:block;height:36px;max-width:180px;border:0;\">{% else %}<span style=\"font-size:20px;font-weight:700;color:#111827;\">{{ shop.name }}</span>{% endif %}</td>\n<td align=\"right\" style=\"font-size:13px;color:#6b7280;\">Order {{ order.name }}</td>\n</tr></table>\n</td></tr>\n<tr><td style=\"padding:24px 32px 4px;\">\n<h1 style=\"margin:0 0 12px;font-size:22px;line-height:1.3;color:#111827;\">Your order is confirmed</h1>\n<p style=\"margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;\">Hi {{ customer.first_name | default: \"there\" }}, your order {{ order.name }} is confirmed and we are getting it ready.</p>\n{% if order.cod_amount > 0 %}<p style=\"margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;\">Please keep <strong>{{ order.cod_amount | money }}</strong> ready to pay on delivery.</p>{% endif %}\n</td></tr>\n{% if order.status_url %}<tr><td style=\"padding:12px 32px 4px;\">\n<a href=\"{{ order.status_url }}\" style=\"display:inline-block;background:{{ accent }};color:#ffffff;text-decoration:none;font-size:15px;font-weight:600;padding:12px 22px;border-radius:8px;\">View your order</a>\n</td></tr>{% endif %}\n<tr><td style=\"padding:8px 32px 0;\">\n<p style=\"margin:0 0 8px;font-size:13px;font-weight:600;text-transform:uppercase;letter-spacing:0.04em;color:#6b7280;\">Order summary</p>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-top:1px solid #e5e7eb;\">\n{% for item in order.line_items %}<tr>\n<td width=\"56\" style=\"padding:12px 12px 12px 0;border-bottom:1px solid #f3f4f6;vertical-align:top;\">{% if item.image_url %}<img src=\"{{ item.image_url }}\" alt=\"\" width=\"48\" height=\"48\" style=\"display:block;width:48px;height:48px;border-radius:8px;object-fit:cover;border:1px solid #e5e7eb;\">{% endif %}</td>\n<td style=\"padding:12px 0;border-bottom:1px solid #f3f4f6;font-size:14px;line-height:1.4;color:#111827;vertical-align:top;\">{{ item.title }}{% if item.variant_title %}<br><span style=\"color:#6b7280;font-size:13px;\">{{ item.variant_title }}</span>{% endif %}<br><span style=\"color:#6b7280;font-size:13px;\">Qty {{ item.quantity }}</span></td>\n<td align=\"right\" style=\"padding:12px 0;border-bottom:1px solid #f3f4f6;font-size:14px;color:#111827;vertical-align:top;white-space:nowrap;\">{{ item.line_price | money }}</td>\n</tr>{% endfor %}\n</table>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"margin-top:8px;\">\n<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Subtotal</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.subtotal_price | money }}</td></tr>\n{% if order.discount_price > 0 %}<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Discount</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">-{{ order.discount_price | money }}</td></tr>{% endif %}\n<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Delivery</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.delivery_price | money }}</td></tr>\n<tr><td style=\"padding:10px 0 6px;font-size:16px;font-weight:700;color:#111827;border-top:1px solid #e5e7eb;\">Total</td><td align=\"right\" style=\"padding:10px 0 6px;font-size:16px;font-weight:700;color:#111827;border-top:1px solid #e5e7eb;\">{{ order.total_price | money }}</td></tr>\n{% if order.paid_amount > 0 %}<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Paid</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.paid_amount | money }}</td></tr>{% endif %}\n{% if order.cod_amount > 0 %}<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\"><strong>To pay on delivery</strong></td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\"><strong>{{ order.cod_amount | money }}</strong></td></tr>{% endif %}\n</table>\n</td></tr>\n{% if order.shipping_address.address %}<tr><td style=\"padding:20px 32px 0;\">\n<p style=\"margin:0 0 6px;font-size:13px;font-weight:600;text-transform:uppercase;letter-spacing:0.04em;color:#6b7280;\">Delivery address</p>\n<p style=\"margin:0;font-size:14px;line-height:1.6;color:#374151;\">{{ order.shipping_address.name }}<br>{{ order.shipping_address.address }}{% if order.shipping_address.area %}, {{ order.shipping_address.area }}{% endif %}{% if order.shipping_address.district %}, {{ order.shipping_address.district }}{% endif %}<br>{{ order.shipping_address.phone }}</p>\n</td></tr>{% endif %}\n<tr><td style=\"padding:28px 32px 28px;\">\n<p style=\"margin:0;padding-top:20px;border-top:1px solid #e5e7eb;font-size:13px;line-height:1.6;color:#6b7280;\">{{ shop.name }}{% if shop.phone %} · {{ shop.phone }}{% endif %}{% if shop.email %} · {{ shop.email }}{% endif %}{% if shop.address %}<br>{{ shop.address }}{% endif %}</p>\n</td></tr>\n</table>\n</td></tr>\n</table>\n</body>\n</html>"}', '{"template":"{% assign accent = shop.accent_color | default: \"#111827\" %}<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Your order is confirmed</title>\n</head>\n<body style=\"margin:0;padding:0;background:#f4f5f7;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"background:#f4f5f7;\">\n<tr><td align=\"center\" style=\"padding:32px 12px;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"max-width:560px;background:#ffffff;border-radius:12px;font-family:-apple-system,BlinkMacSystemFont,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;color:#111827;\">\n<tr><td style=\"padding:28px 32px 0;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\"><tr>\n<td>{% if shop.logo_url %}<img src=\"{{ shop.logo_url }}\" alt=\"{{ shop.name }}\" height=\"36\" style=\"display:block;height:36px;max-width:180px;border:0;\">{% else %}<span style=\"font-size:20px;font-weight:700;color:#111827;\">{{ shop.name }}</span>{% endif %}</td>\n<td align=\"right\" style=\"font-size:13px;color:#6b7280;\">{% if order.name %}Order {{ order.name }}{% endif %}</td>\n</tr></table>\n</td></tr>\n<tr><td style=\"padding:24px 32px 4px;\">\n<h1 style=\"margin:0 0 12px;font-size:22px;line-height:1.3;color:#111827;\">Your order is confirmed</h1>\n<p style=\"margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;\">Hi {{ customer.first_name | default: \"there\" }}, your order {{ order.name }} is confirmed and we are getting it ready.</p>\n{% if order.cod_amount > 0 %}<p style=\"margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;\">Please keep <strong>{{ order.cod_amount | money }}</strong> ready to pay on delivery.</p>{% endif %}\n</td></tr>\n{% if order.status_url %}<tr><td style=\"padding:12px 32px 4px;\">\n<a href=\"{{ order.status_url }}\" style=\"display:inline-block;background:{{ accent }};color:#ffffff;text-decoration:none;font-size:15px;font-weight:600;padding:12px 22px;border-radius:8px;\">View your order</a>\n</td></tr>{% endif %}\n<tr><td style=\"padding:8px 32px 0;\">\n<p style=\"margin:0 0 8px;font-size:13px;font-weight:600;text-transform:uppercase;letter-spacing:0.04em;color:#6b7280;\">Order summary</p>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-top:1px solid #e5e7eb;\">\n{% for item in order.line_items %}<tr>\n<td width=\"56\" style=\"padding:12px 12px 12px 0;border-bottom:1px solid #f3f4f6;vertical-align:top;\">{% if item.image_url %}<img src=\"{{ item.image_url }}\" alt=\"\" width=\"48\" height=\"48\" style=\"display:block;width:48px;height:48px;border-radius:8px;object-fit:cover;border:1px solid #e5e7eb;\">{% endif %}</td>\n<td style=\"padding:12px 0;border-bottom:1px solid #f3f4f6;font-size:14px;line-height:1.4;color:#111827;vertical-align:top;\">{{ item.title }}{% if item.variant_title %}<br><span style=\"color:#6b7280;font-size:13px;\">{{ item.variant_title }}</span>{% endif %}<br><span style=\"color:#6b7280;font-size:13px;\">Qty {{ item.quantity }}</span></td>\n<td align=\"right\" style=\"padding:12px 0;border-bottom:1px solid #f3f4f6;font-size:14px;color:#111827;vertical-align:top;white-space:nowrap;\">{{ item.line_price | money }}</td>\n</tr>{% endfor %}\n</table>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"margin-top:8px;\">\n<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Subtotal</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.subtotal_price | money }}</td></tr>\n{% if order.discount_price > 0 %}<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Discount</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">-{{ order.discount_price | money }}</td></tr>{% endif %}\n<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Delivery</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.delivery_price | money }}</td></tr>\n<tr><td style=\"padding:10px 0 6px;font-size:16px;font-weight:700;color:#111827;border-top:1px solid #e5e7eb;\">Total</td><td align=\"right\" style=\"padding:10px 0 6px;font-size:16px;font-weight:700;color:#111827;border-top:1px solid #e5e7eb;\">{{ order.total_price | money }}</td></tr>\n{% if order.paid_amount > 0 %}<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Paid</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.paid_amount | money }}</td></tr>{% endif %}\n{% if order.cod_amount > 0 %}<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\"><strong>To pay on delivery</strong></td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\"><strong>{{ order.cod_amount | money }}</strong></td></tr>{% endif %}\n</table>\n</td></tr>\n{% if order.shipping_address.address %}<tr><td style=\"padding:20px 32px 0;\">\n<p style=\"margin:0 0 6px;font-size:13px;font-weight:600;text-transform:uppercase;letter-spacing:0.04em;color:#6b7280;\">Delivery address</p>\n<p style=\"margin:0;font-size:14px;line-height:1.6;color:#374151;\">{{ order.shipping_address.name }}<br>{{ order.shipping_address.address }}{% if order.shipping_address.area %}, {{ order.shipping_address.area }}{% endif %}{% if order.shipping_address.district %}, {{ order.shipping_address.district }}{% endif %}<br>{{ order.shipping_address.phone }}</p>\n</td></tr>{% endif %}\n<tr><td style=\"padding:28px 32px 28px;\">\n<p style=\"margin:0;padding-top:20px;border-top:1px solid #e5e7eb;font-size:13px;line-height:1.6;color:#6b7280;\">{{ shop.name }}{% if shop.phone %} · {{ shop.phone }}{% endif %}{% if shop.email %} · {{ shop.email }}{% endif %}{% if shop.address %}<br>{{ shop.address }}{% endif %}</p>\n</td></tr>\n</table>\n</td></tr>\n</table>\n</body>\n</html>"}', '{}', '2026-10-24T23:22:45.560Z', '00000000-0000-4000-8000-000000000001');
